var webext_default = {};

// amr2/src/mirrors/sites/abstract/BaseMirror.ts
var BaseMirror = class {
  constructor(mirrorHelper) {
    this.mirrorHelper = mirrorHelper;
  }
  queryHtml(html, selector, context) {
    const cheerioAPI = (globalThis.cheerio && globalThis.cheerio.load) ? globalThis.cheerio.load(html) : load(html);
    return cheerioAPI(selector, context);
  }
  parseHtml(html) {
    return (globalThis.cheerio && globalThis.cheerio.load) ? globalThis.cheerio.load(html) : load(html);
  }
  /**
   * Wrapper for original mirrorHelper getVariable.
   * Currently we are receiving original html, not sanitized one. so we can
   * pass-through to getVariableFromScript
   */
  getVariable({ doc, variableName }) {
    return this.mirrorHelper.getVariableFromScript(variableName, doc);
  }
  async scriptJson({ target, url, config = {} }) {
    const mergedConfig = {
      ...config,
      headers: {
        accept: "application/json",
        "content-type": "application/json",
        ...config.headers
      }
    };
    const [fetchResponse] = await webext_default.scripting.executeScript({
      target,
      func: function({ url: url2, config: config2 }) {
        return fetch(url2, config2).then((r) => r.json()).catch((e) => {
          console.error(e);
          throw e;
        });
      },
      args: [{ url, config: mergedConfig }]
    });
    if (fetchResponse.error) {
      throw new Error(fetchResponse.error.message);
    }
    return fetchResponse.result;
  }
};

