// Shared by catalogue adapters and the host. Keep all query words, but tolerate
// punctuation, accents and joined words without admitting an unrelated catalogue.
globalThis.__searchTitleMatches = (title, query) => {
  const normalize = value => String(value || "").normalize("NFKD").toLowerCase()
    .replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i")
    .replace(/[^\p{L}\p{N}]+/gu, " ").trim();
  const needle = normalize(query), text = normalize(title);
  return !needle || needle.split(/\s+/).every(word => text.includes(word)) ||
    text.replace(/ /g, "").includes(needle.replace(/ /g, ""));
};

// Follow only the site's own search pagination, with bounded work per source.
// Select series cards rather than all links (which includes chapters and ads).
async function searchHtmlPages(source, firstUrl, selector, titleSelector = "", processor = url => url) {
  const results = [], seen = new Set(), pages = new Set();
  const home = new URL(firstUrl);
  const sameSite = url => url.hostname.replace(/^www\./, '') === home.hostname.replace(/^www\./, '') && url.port === home.port;
  let url = firstUrl;
  for (let page = 0; url && page < 3 && results.length < 600; ++page) {
    if (pages.has(url)) break;
    pages.add(url);
    let doc;
    try { doc = await source.mirrorHelper.loadPage(url, { nocache: true, preventimages: true }); }
    catch (error) { if (results.length) break; throw error; }
    const $ = source.parseHtml(doc);
    if (page === 0 && !$(selector).length &&
        !/no (?:results?|manga|posts)|nothing found|0 results|no matches|tidak ditemukan/i.test($.text()))
      throw new Error('Source search page no longer contains a manga catalogue');
    $(selector).each(function() {
      const node = $(this);
      const title = (titleSelector ? node.find(titleSelector).first().text() : "") || node.attr("title") || node.text();
      const href = node.attr("href");
      if (!title || !href || (/^[a-z][\w+.-]*:/i.test(href) && !/^https?:/i.test(href))) return;
      try {
        const target = new URL(processor(href), url);
        if (!target.origin || !sameSite(target) || !/^https?:$/.test(target.protocol) ||
            /\/(?:chapter[s]?|user|group|genre|tag|author|category)(?:[-/]|$)/i.test(target.pathname)) return;
        const canonical = target.origin + target.pathname + target.search;
        if (seen.has(canonical)) return;
        seen.add(canonical);
        results.push([title.trim(), canonical]);
      } catch (_) {}
    });
    const next = $('a[rel="next"], a.next.page-numbers, .pagination a.next, .paginate a.next').first().attr("href");
    if (!next) break;
    const nextUrl = new URL(next, url);
    // A bogus 'next' link must not leave the search or lose its query parameters.
    const first = new URL(firstUrl);
    const params = Array.from(first.searchParams.entries());
    if (!sameSite(nextUrl) || !params.every(([k,v]) => nextUrl.searchParams.get(k) === v)) break;
    url = nextUrl.href;
  }
  return results;
}

