var MangaStream = class extends BaseMirror {
  constructor(mirrorHelper, mirror, options = {}) {
    super(mirrorHelper);
    this.canListFullMangas = false;
    this.mirrorName = mirror.mirrorName;
    this.mirrorIcon = mirror.mirrorIcon;
    this.domains = mirror.domains;
    this.home = mirror.home;
    this.chapter_url = mirror.chapter_url;
    this.languages = mirror.languages;
    this.disabled = mirror.disabled;
    this.options = {
      ...defaultOptions4,
      ...options
    };
  }
  async getMangaList(search) {
    const self = this;
    const searchApiUrl = this.options.search_url + "wp-admin/admin-ajax.php";
    let apiError;
    if (this.options.search_json) {
      try {
      const json = await this.mirrorHelper.loadJson(searchApiUrl, {
        nocache: true,
        post: true,
        headers: {
          "X-Requested-With": "XMLHttpRequest",
          "Content-type": "application/x-www-form-urlencoded"
        },
        data: {
          action: "ajaxy_sf",
          sf_value: search,
          search: "false"
        }
      });
      const res2 = [];
      const mangas = json.manga[0].all;
      for (const i in mangas) {
        const item = mangas[i];
        res2.push([item["post_title"], self.options.fixSeriesUrl(item["post_link"])]);
      }
      if (res2.some(item => __searchTitleMatches(item[0], search))) return res2;
      } catch (error) { apiError = error; }
    }
    const urlManga = this.options.search_url + `?${this.options.search_field}=` + encodeURIComponent(search) + this.options.search_option;
    try {
      return await searchHtmlPages(this, urlManga, this.options.search_a_sel + ", .listupd .bsx > a",
        ".tt, .ttx, h3", this.options.fixSeriesUrl);
    } catch (error) { throw apiError || error; }
  }
  async getListChaps(urlManga) {
    const doc = await this.mirrorHelper.loadPage(urlManga, { nocache: true, preventimages: true });
    const _self = this;
    const $ = this.parseHtml(doc);
    var res = [];
    $(this.options.chapters_a_sel, doc).each(function(index) {
      let chapter_text = $(this).text().trim();
      if (_self.options.chapters_text_sel !== "") {
        chapter_text = $(_self.options.chapters_text_sel, this).text().trim();
      }
      const chapter_url = _self.options.fixChapterUrl($(this).attr("href") + _self.options.chapter_url_suffix);
      res.push([chapter_text, chapter_url]);
    });
    return res;
  }
  async getCurrentPageInfo(doc, curUrl) {
    const $ = this.parseHtml(doc);
    const manga_url = $(this.options.manga_url_sel, doc).attr("href");
    const manga_name = $(this.options.manga_url_sel, doc).text();
    return {
      name: manga_name.replace(this.options.manga_name_replace, "").trim(),
      currentMangaURL: this.options.fixSeriesUrl(manga_url),
      currentChapterURL: this.options.fixChapterUrl(curUrl)
    };
  }
  async getListImages(doc) {
    const name = this.options.img_src;
    const $ = this.parseHtml(doc);
    const res = [];
    $(this.options.img_sel, doc).each(function(index) {
      res[res.length] = $(this).attr(name);
    });
    return res;
  }
  async getImageUrlFromPage(urlImg) {
    return urlImg;
  }
  isCurrentPageAChapterPage(doc) {
    return this.queryHtml(doc, this.options.page_container_sel).length > 0;
  }
};
// Asura replaced the WordPress reader with a public search API and Astro pages.
// Only links and images rendered by the public reader are consumed.
var AsuraScans = class extends MangaStream {
  async getMangaList(search) {
    const json = await this.mirrorHelper.loadJson("https://api.asurascans.com/api/search?q=" + encodeURIComponent(search));
    if (!Array.isArray(json.data)) throw new Error("Asura search data missing");
    return json.data.filter(item => item.title && item.public_url).map(item => [item.title, new URL(item.public_url, this.home).href]);
  }
  async getListChaps(urlManga) {
    const doc = await this.mirrorHelper.loadPage(urlManga, { nocache: true, preventimages: true });
    const $ = this.parseHtml(doc);
    const chapters = new Map();
    const home = this.home;
    $('a[href*="/chapter/"]').each(function() {
      const href = $(this).attr("href");
      const number = href.match(/\/chapter\/(\d+(?:\.\d+)?)(?:[/?#]|$)/)?.[1];
      if (number) chapters.set(new URL(href, home).href, number);
    });
    return [...chapters].sort((a,b) => Number(b[1]) - Number(a[1])).map(([url, number]) => ["Chapter " + number, url]);
  }
  async getListImages(doc) {
    const $ = this.parseHtml(doc);
    const pages = [];
    $('img[data-page-index]').each(function() {
      const url = $(this).attr("data-src") || $(this).attr("src");
      if (url) pages.push([Number($(this).attr("data-page-index")), url]);
    });
    if (!pages.length) throw new Error("Asura public reader has no accessible page images");
    return pages.sort((a,b) => a[0] - b[0]).map(page => page[1]);
  }
};
var KiryuuCurrent = class extends MangaStream {
  async getMangaList(search) {
    const homeDoc = await this.mirrorHelper.loadPage(this.home, { nocache: true });
    const $ = this.parseHtml(homeDoc);
    const action = $('form[hx-post]').first().attr('hx-post');
    if (!action || !action.includes('action=search') || new URL(action, this.home).origin !== new URL(this.home).origin)
      throw new Error('Kiryuu search form unavailable');
    const doc = await this.mirrorHelper.loadPage(action, {
      method: 'POST', nocache: true, data: new URLSearchParams({ query: search }),
      headers: { 'HX-Request': 'true', Referer: this.home }
    });
    const result = [], parsed = this.parseHtml(doc);
    parsed('#searchResults a[href*="/manga/"]').each(function() {
      result.push([parsed(this).find('h3').text().trim(), parsed(this).attr('href')]);
    });
    return result;
  }
  async getListChaps(urlManga) {
    const url = new URL(urlManga);
    const doc = await this.mirrorHelper.loadPage(this.home.replace(/\/$/, '') + url.pathname, { nocache: true });
    const $ = this.parseHtml(doc), chapters = [], home = this.home;
    $('#chapter-list [data-chapter-number]').each(function() {
      const number = $(this).attr('data-chapter-number');
      const href = $(this).find('a').first().attr('href');
      if (href) chapters.push(['Chapter ' + number, new URL(href, home).href]);
    });
    if (!chapters.length) throw new Error('Kiryuu chapter catalogue unavailable');
    return chapters;
  }
  async getListImages(doc) {
    const $ = this.parseHtml(doc), pages = [];
    $('[data-image-data] img.kstorage-page, [data-image-data] img[data-src], [data-image-data] img[src]').each(function() {
      const url = $(this).attr('data-src') || $(this).attr('src');
      if (url && !url.startsWith('data:')) pages.push(url);
    });
    return [...new Set(pages)];
  }
};
