var defaultOptions5 = {
  base_url: "",
  series_list_selector: '.listupd a[href*="/manga/"]',
  chapter_list_selector: ".eph-num a",
  manga_url_selector: ".allc a",
  img_sel: "#readerarea img",
  urlProcessorSeries: (url) => url,
  urlProcessorChapter: (url) => url
};
var MangaStream_1_1_4 = class extends BaseMirror {
  constructor(mirrorHelper, mirror, options = {}) {
    super(mirrorHelper);
    this.canListFullMangas = false;
    this.mirrorName = mirror.mirrorName;
    this.mirrorIcon = mirror.mirrorIcon;
    this.domains = mirror.domains;
    this.home = mirror.home;
    this.chapter_url = mirror.chapter_url;
    this.languages = mirror.languages;
    this.disabled = mirror.disabled;
    this.options = {
      ...defaultOptions5,
      ...options
    };
  }
  async getMangaList(search) {
    return searchHtmlPages(this, this.options.base_url + "?s=" + encodeURIComponent(search),
      this.options.series_list_selector, ".tt, .ttx, h3", this.options.urlProcessorSeries);
  }
  async getListChaps(urlManga) {
    const doc = await this.mirrorHelper.loadPage(urlManga, { nocache: true, preventimages: true });
    const res = [];
    const self = this;
    const $ = this.parseHtml(doc);
    $(this.options.chapter_list_selector, doc).each(function(index) {
      res.push([$(".chapternum", this).text().trim(), self.options.urlProcessorChapter($(this).attr("href"))]);
    });
    console.debug(res);
    return res;
  }
  async getCurrentPageInfo(doc, curUrl) {
    const $ = this.parseHtml(doc);
    const title = $(this.options.manga_url_selector, doc);
    return {
      name: title.text(),
      currentMangaURL: this.options.urlProcessorSeries(title.attr("href")),
      currentChapterURL: this.options.urlProcessorChapter(curUrl)
    };
  }
  async getListImages(doc) {
    const res = [];
    const regex = /ts_reader\.run\((.*?)\);/g;
    const parts = doc.match(regex);
    if (!Array.isArray(parts) || parts.length === 0) {
      const $ = this.parseHtml(doc);
      const res2 = [];
      $(this.options.img_sel, doc).each(function(index) {
        res2[res2.length] = $(this).attr("src");
      });
      return res2;
    }
    const json = JSON.parse(parts[0].replace("ts_reader.run(", "").replace(");", ""));
    for (const source of json.sources) {
      if (source.images) {
        return source.images;
      }
    }
    return res;
  }
  async getImageUrlFromPage(urlImg) {
    return urlImg;
  }
  isCurrentPageAChapterPage(doc) {
    return this.queryHtml(doc, "div#readerarea").length > 0;
  }
};
// Night Scans moved to Qi Manga. The public catalogue and reader expose JSON;
// the old WordPress selectors silently returned an empty list on the new site.
var NightScansCurrent = class extends MangaStream_1_1_4 {
  async getMangaList(search) {
    const results = [], seen = new Set();
    for (let page = 1; page <= 3; ++page) {
      const endpoint = search ? 'series/search?q=' + encodeURIComponent(search) + '&' : 'series?';
      const json = await this.mirrorHelper.loadJson('https://api.qimanga.com/api/v1/' + endpoint + 'perPage=40&page=' + page);
      if (!Array.isArray(json.data)) throw new Error('Qi Manga search data unavailable');
      let added = 0;
      for (const item of json.data) {
        if (!item.slug || !item.title || seen.has(item.slug)) continue;
        seen.add(item.slug); ++added;
        results.push([item.title, this.home + 'series/' + encodeURIComponent(item.slug), item.alternativeTitles || '']);
      }
      if (!added || !json.next) break;
    }
    return results;
  }
  async getListChaps(urlManga) {
    const slug = new URL(urlManga).pathname.split('/').filter(Boolean).pop();
    const base = this.home + 'series/' + encodeURIComponent(slug);
    const results = [], seen = new Set(), cursors = new Set();
    let cursor = '';
    for (let page = 0; page < 100; ++page) {
      const json = await this.mirrorHelper.loadJson('https://api.qimanga.com/api/v2/series/' + encodeURIComponent(slug) +
        '/chapters?limit=100&sort=desc' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''));
      if (!Array.isArray(json.data)) throw new Error('Qi Manga chapter data unavailable');
      for (const item of json.data) {
        if (!item.slug || seen.has(item.slug) || item.requiresPurchase || item.isFree === false) continue;
        seen.add(item.slug);
        results.push(['Chapter ' + item.number + (item.title ? ' - ' + item.title : ''), base + '/' + encodeURIComponent(item.slug)]);
      }
      if (!json.hasMore) return results;
      if (!json.nextCursor || cursors.has(json.nextCursor) || !json.data.length)
        throw new Error('Qi Manga chapter pagination did not advance');
      cursor = json.nextCursor; cursors.add(cursor);
    }
    throw new Error('Qi Manga chapter catalogue incomplete');
  }
  async getListImages(doc) {
    const $ = this.parseHtml(doc);
    const state = JSON.parse($('#ng-state').text() || '{}');
    for (const entry of Object.values(state)) {
      if (!entry || typeof entry.u !== 'string' || !/\/series\/[^/]+\/chapters\/[^/?]+$/.test(entry.u)) continue;
      const chapter = entry.b;
      if (!chapter || chapter.requiresPurchase || chapter.isFree === false)
        throw new Error('Qi Manga chapter is not publicly available');
      if (Array.isArray(chapter.images)) return chapter.images.slice().sort((a,b) => a.order - b.order).map(image => image.url).filter(Boolean);
    }
    throw new Error('Qi Manga public reader images unavailable');
  }
};
var RizzComic = class extends MangaStream_1_1_4 {
  async getMangaList(search) {
    const json = await this.mirrorHelper.loadJson(this.home + "/Index/live_search", {
      post: true,
      headers: { "X-Requested-With": "XMLHttpRequest" },
      data: { search_value: search }
    });
    if (!Array.isArray(json)) throw new Error("Rizz Comic search data missing");
    return json.filter(item => typeof item.title === "string").map(item => {
      // Match the site's own live-search links, including its series prefix.
      const slug = item.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/-s-/, "s-").replace(/-ll-/, "ll-");
      return [item.title, this.home + "/series/r2311170-" + slug];
    });
  }
};
