// amr2/src/mirrors/sites/SadScans.ts
var SadScans = class extends BaseMirror {
  constructor(amrLoader) {
    super(amrLoader);
    this.mirrorName = "Sad Scans";
    this.canListFullMangas = false;
    this.mirrorIcon = scantradunion_optimized_default;
    this.languages = "tr";
    this.domains = ["sadscans.net", "sadscans.com"];
    this.home = "https://sadscans.net/";
    this.chapter_url = /^\/reader\/.+$/g;
  }
  async getMangaList(search) {
    const doc = await this.mirrorHelper.loadPage(this.home + "seriler", { nocache: true });
    const $ = this.parseHtml(doc);
    const res = [], seen = new Set();
    $('a[href*="/seriler/"]').each((_, element) => {
      const node = $(element), url = this.normalizeUrl(node.attr("href"));
      if (!/^\/seriler\/[^/]+\/?$/.test(new URL(url).pathname) || seen.has(url)) return;
      const title = node.find("h2, h3").first().text().trim() || node.find("img").attr("alt") || node.text().trim();
      if (title) { seen.add(url); res.push([title, url]); }
    });
    if (!res.length) throw new Error("Sad Scans katalogu tarayicida yuklenemedi; kaynak sayfasini uygulama tarayicisinda acin");
    return res;
  }
  async getListChaps(urlManga) {
    const url = this.normalizeUrl(urlManga);
    const doc = await this.mirrorHelper.loadPage(url, { nocache: true });
    const $ = this.parseHtml(doc);
    const slug = new URL(url).pathname.split("/").filter(Boolean)[1];
    const res = [], seen = new Set();
    $('a[href*="/reader/"]').each((_, element) => {
      const node = $(element), target = this.normalizeUrl(node.attr("href"));
      if (!new URL(target).pathname.startsWith("/reader/" + slug + "/") || seen.has(target)) return;
      const title = node.attr("title") || node.text().trim();
      if (title) { seen.add(target); res.push([title, target]); }
    });
    // Next.js SEO data contains only 20 old chapters, not the full catalogue.
    // Never replace the user's saved chapters with that metadata preview.
    if (!res.length) throw new Error("Sad Scans bolum listesi JavaScript ile yukleniyor; tarayici taramasi gerekli");
    return res;
  }
  normalizeUrl(value) {
    const url = new URL(value, this.home);
    if (!/^(?:www\.)?sadscans\.(?:net|com)$/.test(url.hostname)) throw new Error("Unexpected Sad Scans host");
    return this.home.replace(/\/$/, "") + url.pathname.replace(/^\/series\//, "/seriler/") + url.search;
  }
  async getCurrentPageInfo(doc, curUrl) {
    const $ = this.parseHtml(doc);
    const current = this.normalizeUrl(curUrl), slug = new URL(current).pathname.split("/")[2];
    const mgtitle = $('a[href*="/seriler/' + slug + '"]').first();
    return {
      name: mgtitle.text().trim() || $("h1").first().text().trim(),
      currentMangaURL: this.home + "seriler/" + slug,
      currentChapterURL: current
    };
  }
  async getListImages(doc, curUrl, sender) {
    const res = [], seen = new Set();
    const $ = this.parseHtml(doc);
    // Match the current chapter directory; covers and SEO thumbnails are not pages.
    const id = new URL(curUrl).pathname.split("/").filter(Boolean).pop();
    $("img").each((_, element) => {
      const node = $(element), raw = node.attr("data-src") || node.attr("src");
      if (!raw) return;
      const target = new URL(raw, this.home);
      if (target.protocol !== "https:" || !target.pathname.includes("/" + id + "/") || seen.has(target.href)) return;
      seen.add(target.href); res.push(target.href);
    });
    if (!res.length) throw new Error("Sad Scans okuyucu sayfalari yuklenemedi; tarayici taramasi gerekli");
    return res;
  }
  isCurrentPageAChapterPage(doc, curUrl) {
    return /^\/reader\//.test(new URL(curUrl).pathname);
  }
  async getImageUrlFromPage(urlImage) {
    return urlImage;
  }
};

