// amr2/src/mirrors/icons/mangakawaii-optimized.png
var mangakawaii_optimized_default = "./mangakawaii-optimized-2E23VCYX.png";

// amr2/src/mirrors/sites/MangaKawaii.ts
var MangaKawaii = class extends BaseMirror {
  constructor(amrLoader) {
    super(amrLoader);
    this.mirrorName = "MangaKawaii";
    this.canListFullMangas = false;
    this.mirrorIcon = mangakawaii_optimized_default;
    this.languages = "fr";
    this.domains = ["mangakawaii.fr", "mangakawaii.io"];
    this.home = "https://www.mangakawaii.fr";
    this.chapter_url = /^\/manga\/[^/]+\/(?!chapitres(?:\/|$))[^/]+\/?$/;
  }
  async getMangaList(search) {
    const doc = await this.mirrorHelper.loadPage(this.home + "/recherche?q=" + encodeURIComponent(search), { nocache: true });
    const $ = this.parseHtml(doc);
    const res = [], seen = new Set();
    $("a.mk-card[href]").each((_, element) => {
      const node = $(element), url = new URL(node.attr("href"), this.home);
      // The same search also contains anime and light novels.
      if (url.origin !== this.home || !/^\/manga\/[^/]+\/?$/.test(url.pathname) || seen.has(url.href)) return;
      const title = node.find(".mk-display").first().text().trim() || node.find("img").attr("alt");
      if (title) { seen.add(url.href); res.push([title, url.href]); }
    });
    if (!res.length && !/résultats?|aucun/i.test($("h1").text())) throw new Error("MangaKawaii search catalogue missing");
    return res;
  }
  async getListChaps(urlManga) {
    const url = this.normalizeUrl(urlManga);
    let doc = await this.mirrorHelper.loadPage(url, { nocache: true });
    let $ = this.parseHtml(doc);
    const endpoint = $("#chapitres").attr("data-url");
    if (!endpoint || new URL(endpoint, url).href !== url.replace(/\/$/, "") + "/chapitres")
      throw new Error("MangaKawaii chapter catalogue missing");
    const res = [], seen = new Set();
    const limitedLicense = /seuls les \d+ derniers chapitres restent lisibles/i.test(doc);
    let page = 1;
    while (true) {
      $(".ch-row[data-number]").each((_, element) => {
        const row = $(element), href = row.find("a[href]").first().attr("href");
        if (!href) return; // Licensed/locked rows are not readable chapters.
        const target = new URL(href, url);
        if (target.origin !== this.home || !target.pathname.startsWith(new URL(url).pathname.replace(/\/$/, "") + "/") || seen.has(target.href)) return;
        seen.add(target.href); res.push(["Chapitre " + row.attr("data-number"), target.href]);
      });
      const rawNext = $("[data-ch-next]").first().attr("data-ch-next");
      if (!rawNext || limitedLicense) break;
      const next = Number(rawNext);
      if (!Number.isInteger(next) || next <= page || next > 100) throw new Error("MangaKawaii chapter pagination incomplete");
      page = next;
      doc = await this.mirrorHelper.loadPage(endpoint + "?page=" + page + "&ch=&order=desc", {
        nocache: true, headers: { "X-Requested-With": "fetch", "Referer": url }
      });
      $ = this.parseHtml(doc);
      if (!$("[data-ch-list], [data-ch-grid]").length) throw new Error("MangaKawaii chapter page missing");
    }
    return res;
  }
  normalizeUrl(value) {
    const url = new URL(value, this.home);
    if (/^(?:www\.)?mangakawaii\.(?:io|fr)$/.test(url.hostname)) {
      // Old bookmarks used /manga/slug/fr/chapter/1; V5 has no locale/page suffix.
      const parts = url.pathname.split("/").filter(Boolean);
      if (parts[0] === "manga" && parts.length >= 4 && /^[a-z]{2}$/.test(parts[2])) parts.splice(2,1);
      return this.home + "/" + parts.slice(0,3).join("/");
    }
    throw new Error("Unexpected MangaKawaii host");
  }
  readerData(doc) {
    const $ = this.parseHtml(doc);
    let raw;
    $("[x-data]").each((_, element) => {
      const value = $(element).attr("x-data");
      if (value && value.startsWith("rd(JSON.parse(")) raw = value;
    });
    const match = raw && raw.match(/^rd\(JSON\.parse\('((?:\\.|[^'\\])*)'\)\)$/s);
    if (!match) throw new Error("MangaKawaii reader data missing");
    // Decode the JS string literal as data. Never execute page-supplied code.
    const escapes = { b:"\b", f:"\f", n:"\n", r:"\r", t:"\t" };
    const json = match[1].replace(/\\(?:u([0-9a-f]{4})|([\\/'"bfnrt]))/gi,
      (_, hex, ch) => hex ? String.fromCharCode(parseInt(hex,16)) : (escapes[ch] || ch));
    return JSON.parse(json);
  }
  async getCurrentPageInfo(doc, curUrl) {
    const data = this.readerData(doc);
    return {
      name: data.title,
      currentMangaURL: this.normalizeUrl(data.back),
      currentChapterURL: this.normalizeUrl(curUrl)
    };
  }
  async getListImages(doc) {
    const data = this.readerData(doc);
    if (!Array.isArray(data.imgs) || !data.imgs.length) throw new Error("MangaKawaii pages missing or unavailable");
    return data.imgs.filter(url => typeof url === "string" && /^https:\/\//.test(url));
  }
  isCurrentPageAChapterPage(doc) {
    return this.queryHtml(doc, "img#pg-1").length > 0;
  }
  async getImageUrlFromPage(urlImage) {
    return urlImage;
  }
};

