// amr2/src/mirrors/sites/Dm5.ts
var Dm5 = class extends BaseMirror {
  constructor(amrLoader) {
    super(amrLoader);
    this.mirrorName = "DM5";
    this.canListFullMangas = false;
    this.mirrorIcon = dm5_optimized_default;
    this.languages = "cn";
    this.domains = ["dm5.com"];
    this.home = "https://www.dm5.com";
    this.chapter_url = /^\/m[0-9]+\/$/g;
  }
  async getMangaList(search) {
    const doc = await this.mirrorHelper.loadPage(
      this.home + "/search.ashx?d=" + (/* @__PURE__ */ new Date()).getTime() + "&t=" + search + "&language=1",
      {
        nocache: true,
        preventimages: true
      }
    );
    const res = [];
    const _self = this;
    const $ = this.parseHtml(doc);
    $("li").each(function() {
      let url = $(this).attr("onclick");
      const st = url.indexOf("'"), en = url.lastIndexOf("'");
      url = url.substring(st + 1, en);
      if ($(this).attr("value") !== "0") {
        res[res.length] = [$(".left", $(this)).text(), _self.home + url];
      }
    });
    return res;
  }
  async getListChaps(urlManga) {
    let doc = await this.mirrorHelper.loadPage(urlManga, { nocache: true, preventimages: true });
    let $ = this.parseHtml(doc);
    if ($("#checkAdult", doc).length > 0) {
      this.mirrorHelper.setCookie({
        // set the cookie on dm5 domain
        name: "isAdult",
        value: "1",
        path: "/",
        url: urlManga,
        domain: "www.dm5.com",
        expirationDate: (/* @__PURE__ */ new Date()).getTime() + 24 * 60 * 60 * 1e3
      });
      doc = await this.mirrorHelper.loadPage(urlManga, {
        // and reload the page
        nocache: true,
        preventimages: true
      });
      $ = this.parseHtml(doc);
    }
    let res = [];
    const _self = this;
    $("#chapterlistload li > a").each(function(index) {
      $("span", $(this)).remove();
      let name = $(this).text();
      if ($(".title", $(this)).length > 0) name = $(".title", $(this)).text();
      res[res.length] = [name, _self.home + $(this).attr("href")];
    });
    if ($("#chapterlistload .cover", doc).length > 0) res = res.reverse();
    return res;
  }
  async getCurrentPageInfo(doc, curUrl) {
    const $ = this.parseHtml(doc);
    const mg = $(".view-header-2 .title a[href!='/']");
    return {
      name: mg.attr("title"),
      currentMangaURL: this.home + mg.attr("href"),
      currentChapterURL: this.home + this.mirrorHelper.getVariableFromScript("DM5_CURL", doc)
    };
  }
  async getListImages(doc) {
    const $ = this.parseHtml(doc);
    const res = [];
    $("img.load-src").each(function() {
      res.push($(this).attr("data-src"));
    });
    return res;
  }
  isCurrentPageAChapterPage(doc, curUrl) {
    return this.chapter_url.test(new URL(curUrl).pathname);
  }
  async getImageUrlFromPage(urlImage) {
    return urlImage;
  }
};

// amr2/src/mirrors/sites/ReaperScans.ts
var ReaperScans = class extends BaseMirror {
  constructor(amrLoader) {
    super(amrLoader);
    this.mirrorName = "Reaper Scans";
    this.canListFullMangas = false;
    this.mirrorIcon = reaperscans_optimized_default;
    this.languages = "en";
    this.domains = ["reaperscans.com", "reapercomics.com"];
    this.home = "https://reaperscans.com";
    this.apiBaseUrl = "https://api.reaperscans.com/";
    this.chapter_url = /^\/series\/.+\/chapter-.+/g;
  }
  async getMangaList(search) {
    const json = await this.mirrorHelper.loadJson(`${this.apiBaseUrl}query?adult=true&query_string=${search}`);
    const res = [];
    for (const series of json.data) {
      res.push([series.title.trim(), `${this.home}/series/${series.series_slug}`]);
    }
    return res;
  }
  async getListChaps(urlManga) {
    const doc = await this.mirrorHelper.loadPage(urlManga, { nocache: true, preventimages: true });
    const res = [];
    const $ = this.parseHtml(doc);
    const regex = /{\\\"series_id\\\":(\d+)}]/g;
    const matches = regex.exec(doc);
    const seriesId = matches[1];
    const json = await this.mirrorHelper.loadJson(
      `${this.apiBaseUrl}chapter/query?page=1&perPage=1000&series_id=${seriesId}`
    );
    for (const chap of json.data) {
      if (chap.price == 0) {
        res.push([
          chap.chapter_name + (chap.chapter_title !== null && chap.chapter_title.length > 0 ? " - " + chap.chapter_title : ""),
          this.home + `/series/${chap.series.series_slug}/${chap.chapter_slug}`
        ]);
      }
    }
    return res;
  }
  async getCurrentPageInfo(doc, curUrl) {
    const $ = this.parseHtml(doc);
    const mgtitle = $("h2.text-xxs");
    return {
      name: mgtitle.text(),
      currentMangaURL: curUrl.split("/", 5).join("/"),
      currentChapterURL: curUrl
    };
  }
  async getListImages(doc, curUrl) {
    const res = [];
    const url = this.apiBaseUrl + new URL(curUrl).pathname.replace("/series/", "chapter/");
    const json = await this.mirrorHelper.loadJson(url);
    const uniqueImages = [];
    if (json.chapter.chapter_type == "Comic") {
      for (let image of json.chapter.chapter_data.images) {
        let imageName = image.split("/").pop().split(".")[0];
        if (imageName.endsWith("f")) {
          imageName = imageName.substring(0, imageName.length - 1);
        }
        if (uniqueImages.includes(imageName)) {
          continue;
        }
        uniqueImages.push(imageName);
        if (!image.startsWith("https")) {
          image = "https://media.reaperscans.com/file/4SRBHm/" + image;
        }
        res.push(image);
      }
      console.debug(res);
    }
    if (json.chapter.chapter_type == "Novel") {
      const $ = this.parseHtml(json.chapter.chapter_content);
      const lines = [];
      const lineLengthBeforeWrap = 140;
      const wrap = (s, w) => s.replace(new RegExp(`(?![^\\n]{1,${w}}$)([^\\n]{1,${w}})\\s`, "g"), "$1:|:");
      for (const elem of $("p")) {
        const line = $(elem).text().trim();
        if (line.length > lineLengthBeforeWrap) {
          const parts = wrap(line, lineLengthBeforeWrap).split(":|:");
          lines.push(...parts);
        } else {
          lines.push(line);
        }
      }
      for (const line of lines) {
        res.push(await this.createImageFromText(line));
      }
    }
    return res;
  }
  async createImageFromText(text) {
    const dark = this.mirrorHelper.getOption("darkreader") === 1;
    const height = 32;
    const canvas = new OffscreenCanvas(1e3, height);
    const context = canvas.getContext("2d");
    context.rect(0, 0, 1e3, height);
    context.fillStyle = dark ? "black" : "ghostwhite";
    context.fill();
    context.font = "15px Helvetica";
    context.fillStyle = dark ? "ghostwhite" : "black";
    context.fillText(text, 7, height - 7);
    const blob = await canvas.convertToBlob();
    const base64String = await new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result);
      reader.readAsDataURL(blob);
    });
    return base64String;
  }
  isCurrentPageAChapterPage(doc) {
    return this.queryHtml(doc, ".container img[loading='lazy']").length > 0;
  }
  async getImageUrlFromPage(urlImage) {
    return urlImage;
  }
};

